from dsl import *
VH = 'vietnam-hanoi'; OP = ['vietnam-operations']
for k, n_ in [('cay-me-my-tho', 'Cây Me, Long An commune'), ('binh-ba', 'Bình Ba'), ('dat-do', 'Đất Đỏ'), ('hoa-thinh', 'Hòa Thịnh')]:
    NP(k, n_)
A('1960-0224-cayme', '1960-02-24', VH, 'Mỹ Tho. Unit 514, the province\'s armed force, dressed as Saigon troops, lies in ambush at Cây Me, Long An commune, Châu Thành, on Route 4, for the truck carrying the garrison\'s pay, Feb. 24. The attack is not carried out.', 'II, 335', place='cay-me-my-tho', also=OP)
A('1960-0225-mytho', '1960-02-25', VH, 'Mỹ Tho. The province calls the rising in all its communes, Feb. 25. In Long An commune, Châu Thành, the chosen point, the people with the province\'s armed force burn the watch post and seize the hamlet chiefs and neighborhood heads for a warning. Along the Nguyễn Văn Tiếp canal, from Hưng Thạnh to Thiên Hộ, they beat drums and wooden clappers and tear down the neighborhood signs and anticommunist slogans. Battalion 514 does armed propaganda in seven communes. The political force too weak, the province does not take control.', 'II, 335', place='my-tho', also=OP)
A('1960-0225-gocong', '1960-02-25', VH, 'Gò Công. The night of Feb. 25 an armed team in East Gò Công and Vàm Láng kills the village representative Chớ and hangs banners urging the rising. The Saigon side finds the team, kills four and takes one. The rising fails.', 'II, 335', place='go-cong', band_='night', also=OP, check='the history gives Chớ\'s post as "đại diện" (representative) only.')
A('1960-0330-binhba', '1960-03-30', VH, 'Bà Rịa. The evening of Mar. 30 Company 40, the province\'s armed force, marches to a point 100 m from the three posts (Civil Guard, Civil Guard rural force and military police) at the Bình Ba rubber plantation, on Route 2, 8 km north of Bà Rịa. Two squads block the relief on both ends of Route 2; the rest in three prongs hit the posts with grenades and satchel charges. Eight weapons and over a ton of ammunition taken, the military police post chief seized. The rising of the rubber workers of Xà Bang, Xuân Sơn, Ngãi Giao and Sông Cầu follows.', 'II, 346–47', place='binh-ba', band_='evening', also=OP, check='the hour of the attack; the history gives the evening of the march to the assembly point.')
A('1960-0406-datdo', '1960-04-06', VH, 'Bà Rịa. The night of Apr. 6 the Đất Đỏ district\'s armed propaganda team destroys the Civil Guard post of Long Mỹ commune and takes four weapons. The people rise, beat drums and clappers and burn the commune council\'s house; the Saigon side in the place flees to the district seat. The team then works along Routes 52 and 23, backing the risings of Đất Đỏ, Long Hội Mỹ, Long Tân, Long Điền and An Ngãi.', 'II, 347', place='dat-do', band_='night', also=OP)
A('1960-04-longkhanh', '1960-04', VH, 'Long Khánh. From April, moved by the Bà Rịa rising, the people of many places rise to kill the oppressors, break the controls and take the commune and hamlet governments, in various degrees.', 'II, 347', when='Apr.', place='long-khanh', also=OP, check='the day.')
A('1960-0506-caytho', '1960-05-06', VH, 'Cần Thơ. May 6 four Saigon battalions sweep Rạch Ông Dựa, Trường Thành, Ô Môn. The Tây Đô Battalion with Ô Môn\'s district force beats the sweep: 200 killed, six taken, 30 weapons and much equipment, by the history\'s count. The first large sweep the province beats.', 'II, 341–42', place='can-tho', also=OP)
A('1960-0612-konsam', '1960-06-12', VH, 'Trị–Thiên. June 12 Kon Sâm kills a Saigon major with a poisoned crossbow bolt in the hamlet of Kon Kô.', 'II, 351', also=OP, tags=['ok:fields-place'], check='the history does not name the province of Kon Kô.')
A('1960-07-laudut', '1960-07', VH, 'Thừa Thiên. In July the guerrillas and young men of La Đụt kill three Saigon men from the A Lưới post and take three weapons.', 'II, 351', when='July', also=OP, tags=['ok:fields-place'], check='the day.')
A('1960-07-tuoimuoi', '1960-07', VH, 'Quảng Trị. In July the province\'s local troops destroy the Tuồi Muồi post and a platoon. The rising spreads, mostly south of Route 9.', 'II, 351', when='July', place='quang-tri-province', also=OP, check='the day.')
A('1960-10-thuathien', '1960-10', VH, 'Thừa Thiên. In October, as Saigon troops drive the people into concentration camps and the people flee to the forest and ask for arms, the Provincial Committee calls the rising everywhere. The province\'s armed force begins by killing the Cần Lao party\'s canton chief at Khe Tranh. Two large struggles of tens of villages follow at Hương Lâm and Phong Lâm: the two canton chiefs killed, the Saigon government declared abolished, self-government and guerrilla squads set up. Saigon pulls out of Tuồi Muồi, Tà Rụt, Trại Cá, Sa Trần and Ly Tông and draws back to A So, A Lưới, Nam Đông and Khe Tre.', 'II, 351–52', when='Oct.', place='thua-thien', also=OP, check='the day.')
A('1960-1111-tuyhoa', '1960-11-11', VH, 'Phú Yên. The night of Nov. 11 a team of Tuy Hòa district enters the house of Nguyễn Y Chi, the district police, and kills him in bed.', 'II, 381', place='tuy-hoa', band_='night', also=OP, check='the history says Nguyễn Ân, hamlet chief of Hòa Xuân, was killed too on the road to Lạc Long hamlet, no day given.')
A('1960-1222-hoathinh', '1960-12-22', VH, 'Phú Yên. The night of Dec. 22 the rising of Hòa Thịnh commune, Tuy Hòa, the Provincial Committee\'s trial point. The district\'s armed work teams in three prongs hit the Civil Guard platoon at the Mỹ Xuân market, the commune council\'s seat at Mỹ Điền and the commune deputy\'s house at Phú Hữu: the platoon wiped out, all its arms taken; the deputy Tín seized; the council seized at a year-end party. A mass meeting at Mỹ Xuân declares the commune\'s government abolished and a self-government set up. The first commune of Phú Yên\'s plain taken.', 'II, 381–82', place='hoa-thinh', band_='night', also=OP, check='the hour.')
A('1960-0717-hoaiduc', '1960-07-17', VH, 'Bình Thuận. July 17 a reconnaissance team under Phạm Hoài Chương goes to prepare the ground for the attack on the Hoài Đức subsector. The Provincial Committee had decided on a secret, surprise attack to break the Bắc Ruộng camp and take the people to the base by the end of July. The command: Phạm Hoài Chương, chief; Lê Triều, commissar; Nguyễn Thành and Nguyễn Thanh Đức, deputies.', 'II, 373', place='hoai-duc', names=['Phạm Hoài Chương'], also=OP, check='the day of the decision.')
A('1960-0728-hoaiduc', '1960-07-28', VH, 'Bình Thuận. The afternoon of July 28 all the forces of the Hoài Đức attack, Unit 2/9, three men of Tánh Linh district and 100 porters, march to the assembly point.', 'II, 373', band_='afternoon', also=OP, tags=['ok:fields-place'], check='the place of the assembly point; the history gives none.')
A('1960-0730-hoaiduc', '1960-07-30', VH, 'Bình Thuận. 2 p.m., July 30, the unit of the Hoài Đức attack holds its ceremony of setting out.', 'II, 373', time='14:00', also=OP, tags=['ok:fields-place'])
